  5	  AC: @ui-task-board ac-4 — Active Fleet row
  6	  AC: @ui-task-board ac-5 — Real-time WebSocket updates
  7	  AC: @ui-task-board ac-6 — Task action buttons in modal
  8	-->
  9	<script lang="ts">
 10		import { page } from '$app/stores';
 11		import { onMount, onDestroy } from 'svelte';
 12		import type { TaskSummary, BroadcastEvent } from '@kynetic-ai/shared';
 13		import { fetchTasks, fetchAgentStatus, type AgentStatus } from '$lib/api';
 14		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 15		import { getProjectVersion } from '$lib/stores/project.svelte';
 16		import { distributeToColumns, type BoardColumn } from '$lib/components/board/board-utils';
 17		import BoardColumnComponent from '$lib/components/board/BoardColumn.svelte';
 18		import ActiveFleetRow from '$lib/components/board/ActiveFleetRow.svelte';
 19		import TaskDetailModal from '$lib/components/board/TaskDetailModal.svelte';
 20		import BoardSkeleton from '$lib/components/board/BoardSkeleton.svelte';
 21		import LayoutGrid from '@lucide/svelte/icons/layout-grid';
 22		import List from '@lucide/svelte/icons/list';
 23		import { Button } from '$lib/components/ui/button';
 24		import { base } from '$app/paths';
 25	
 26		let tasks = $state<TaskSummary[]>([]);
 27		let columns = $state<BoardColumn[]>([]);
 28		let loading = $state(true);
 29		let error = $state('');
 30		let agentStatus = $state<AgentStatus | null>(null);
 31	
 32		// AC: @ui-task-board ac-4 — Accumulated output lines per agent session
 33		const MAX_OUTPUT_LINES = 3;
 34		let agentOutputLines = $state<Record<string, string[]>>({});
 35	
 36		// AC: @ui-task-board ac-4 — Lookup map: task_ref (@ULID or @slug) → title
 37		let taskTitles = $derived(
 38			Object.fromEntries(
 39				tasks.flatMap((t) => {
 40					const entries: [string, string][] = [
 41						[`@${t._ulid}`, t.title]
 42					];
 43					for (const slug of t.slugs) {
 44						entries.push([`@${slug}`, t.title]);
 45					}
 46					return entries;
 47				})
 48			)
 49		);
 50	
 51		// Detail modal state
 52		let modalOpen = $state(false);
 53		let selectedTaskRef = $state<string | null>(null);
 54	
 55		// Track last processed URL ref to avoid infinite loops
 56		let lastProcessedRef = $state('');
 57	
 58		$effect(() => {
 59			// Re-derive columns whenever tasks change
 60			columns = distributeToColumns(tasks);
 61		});
 62	
 63		// AC: @ui-task-board ac-5 — Reload on project change
 64		$effect(() => {
 65			const version = getProjectVersion();
 66			if (version > 0) {
 67				loadBoard();
 68			}
 69		});
 70	
 71		// Open task detail from URL param
 72		$effect(() => {
 73			const urlRef = $page.url.searchParams.get('ref');
 74			if (urlRef && urlRef !== lastProcessedRef) {
 75				lastProcessedRef = urlRef;
 76				selectedTaskRef = urlRef;
 77				modalOpen = true;
 78			}
 79		});
 80	
 81		async function loadBoard() {
 82			loading = true;
 83			error = '';
 84			try {
 85				const [taskResponse, statusResponse] = await Promise.all([
 86					fetchTasks({ limit: 500 }),
 87					fetchAgentStatus().catch(() => null)
 88				]);
 89				tasks = taskResponse.items;
 90				agentStatus = statusResponse;
 91			} catch (err) {
 92				error = err instanceof Error ? err.message : 'Failed to load board';
 93			} finally {
 94				loading = false;
 95			}
 96		}
 97	
 98		function handleCardClick(task: TaskSummary) {
 99			selectedTaskRef = task._ulid;
100			modalOpen = true;
101		}
102	
103		function handleTaskUpdated() {
104			loadBoard();
105		}
106	
107		// AC: @ui-task-board ac-5 — WebSocket real-time updates
108		function handleTaskUpdate(event: BroadcastEvent) {
109			loadBoard();
110		}
111	
112		// AC: @ui-task-board ac-4 — Refresh agent status on agent events
113		function handleAgentUpdate(event: BroadcastEvent) {
114			// AC: @ui-task-board ac-4 — Accumulate text chunks for last few lines of output
115			if (event.event === 'agent_text_chunk' && event.data?.session_id && event.data?.text) {
116				const sessionId = event.data.session_id as string;
117				const text = event.data.text as string;
118				const newLines = text.split('\n').filter((l: string) => l.trim().length > 0);
119				if (newLines.length > 0) {
120					const existing = agentOutputLines[sessionId] ?? [];
121					agentOutputLines[sessionId] = [...existing, ...newLines].slice(-MAX_OUTPUT_LINES);
122				}
123				return;
124			}
125	
126			// Invocation lifecycle events — refresh status and clean up stale output
127			fetchAgentStatus()
128				.then((status) => {
129					agentStatus = status;
130					// Clean up output lines for sessions no longer active
131					const activeSessions = new Set(
132						status.active_invocations.map((inv) => inv.session_id)
133					);
134					for (const sessionId of Object.keys(agentOutputLines)) {
135						if (!activeSessions.has(sessionId)) {
136							delete agentOutputLines[sessionId];
137						}
138					}
139				})
140				.catch(() => {});
141		}
142	
143		// Polling for agent elapsed time updates
144		let agentPollTimer: ReturnType<typeof setInterval> | undefined;
145	
146		onMount(() => {
147			loadBoard();
148	
149			// AC: @ui-task-board ac-5 — Subscribe to task and agent updates
150			subscribe(['tasks', 'agents']);
151			on('tasks', handleTaskUpdate);
152			on('agents', handleAgentUpdate);
153	
154			// Poll agent status every 5s for elapsed time updates
155			agentPollTimer = setInterval(() => {
156				fetchAgentStatus()
157					.then((status) => {
158						agentStatus = status;
159					})
160					.catch(() => {});
161			}, 5000);
162		});
163	
164		onDestroy(() => {
165			off('tasks', handleTaskUpdate);
166			off('agents', handleAgentUpdate);
167			unsubscribe(['tasks', 'agents']);
168			if (agentPollTimer) clearInterval(agentPollTimer);
169		});
170	</script>
171	
172	<div class="flex flex-col h-full">
173		<!-- Header -->
174		<div class="flex items-center justify-between p-6 pb-0">
