203			<div class="mx-6 mt-4 bg-destructive/10 text-destructive p-4 rounded-lg" role="alert" data-testid="board-error">
204				{error}
205			</div>
206		{/if}
207	
208		<!-- Loading skeleton -->
209		{#if loading}
210			<BoardSkeleton />
211		{:else if tasks.length === 0}
212			<!-- Empty state -->
213			<div class="flex flex-col items-center justify-center flex-1 py-16" data-testid="board-empty">
214				<LayoutGrid class="size-12 text-muted-foreground/30 mb-4" />
215				<h2 class="text-lg font-medium text-muted-foreground mb-1">No tasks yet</h2>
216				<p class="text-sm text-muted-foreground">
217					Create tasks using <code class="bg-muted px-1 rounded text-xs">kspec task add</code>
218				</p>
219			</div>
220		{:else}
221			<!-- AC: @ui-task-board ac-4 — Active Fleet Row -->
222			<div class="px-6 pt-4">
223				<ActiveFleetRow status={agentStatus} outputLines={agentOutputLines} {taskTitles} />
224			</div>
225	
226			<!-- AC: @ui-task-board ac-1 — Kanban Columns -->
