230				{/each}
231			</div>
232		{/if}
233	</div>
234	
235	<!-- AC: @ui-task-board ac-3, ac-6 — Detail Modal -->
236	<TaskDetailModal
237		bind:open={modalOpen}
238		bind:taskRef={selectedTaskRef}
239		onTaskUpdated={handleTaskUpdated}
