  1	/**
  2	 * Board utility functions for Kanban column logic.
  3	 *
  4	 * AC: @ui-task-board ac-1 — Column distribution logic
  5	 */
  6	
  7	import type { TaskSummary } from '@kynetic-ai/shared';
  8	
  9	export type ColumnId = 'backlog' | 'ready' | 'in_progress' | 'review' | 'done';
 10	
 11	export interface BoardColumn {
 12		id: ColumnId;
 13		label: string;
 14		tasks: TaskSummary[];
 15	}
 16	
 17	/**
 18	 * Status color mapping using design system tokens.
 19	 * Returns both bg and fg CSS variable references.
 20	 */
 21	export function getStatusClasses(status: string): { bg: string; fg: string; label: string } {
 22		const map: Record<string, { bg: string; fg: string; label: string }> = {
 23			pending: {
 24				bg: 'bg-status-pending',
 25				fg: 'text-status-pending-fg',
 26				label: 'Pending'
 27			},
 28			in_progress: {
 29				bg: 'bg-status-in-progress',
 30				fg: 'text-status-in-progress-fg',
 31				label: 'In Progress'
 32			},
 33			pending_review: {
 34				bg: 'bg-status-pending-review',
 35				fg: 'text-status-pending-review-fg',
 36				label: 'Review'
 37			},
 38			needs_work: {
 39				bg: 'bg-status-needs-work',
 40				fg: 'text-status-needs-work-fg',
 41				label: 'Needs Work'
 42			},
 43			completed: {
 44				bg: 'bg-status-completed',
 45				fg: 'text-status-completed-fg',
 46				label: 'Completed'
 47			},
 48			blocked: {
 49				bg: 'bg-status-blocked',
 50				fg: 'text-status-blocked-fg',
 51				label: 'Blocked'
 52			},
 53			cancelled: {
 54				bg: 'bg-status-cancelled',
 55				fg: 'text-status-cancelled-fg',
 56				label: 'Cancelled'
 57			}
 58		};
 59		return map[status] || { bg: 'bg-muted', fg: 'text-muted-foreground', label: status };
 60	}
 61	
 62	/**
 63	 * Distribute tasks into Kanban columns.
 64	 *
 65	 * AC: @ui-task-board ac-1
 66	 * - Backlog: pending + manual_only or unassessed automation
 67	 * - Ready: pending + eligible automation
 68	 * - In Progress: in_progress + needs_work
 69	 * - Review: pending_review
 70	 * - Done: completed (recent — last 20)
 71	 *
 72	 * Blocked and cancelled are indicators on individual cards, not separate columns.
 73	 */
 74	export function distributeToColumns(tasks: TaskSummary[]): BoardColumn[] {
 75		const backlog: TaskSummary[] = [];
 76		const ready: TaskSummary[] = [];
 77		const inProgress: TaskSummary[] = [];
 78		const review: TaskSummary[] = [];
 79		const done: TaskSummary[] = [];
 80	
 81		for (const task of tasks) {
 82			switch (task.status) {
 83				case 'pending': {
 84					const auto = task.automation;
 85					if (auto === 'eligible') {
 86						ready.push(task);
 87					} else {
 88						// manual_only, unassessed, or undefined → backlog
 89						backlog.push(task);
 90					}
 91					break;
 92				}
 93				case 'in_progress':
 94				case 'needs_work':
 95					inProgress.push(task);
 96					break;
 97				case 'pending_review':
 98					review.push(task);
 99					break;
100				case 'completed':
101					done.push(task);
102					break;
103				case 'blocked':
104					// Show blocked tasks in their original column context (in_progress column)
105					inProgress.push(task);
106					break;
107				case 'cancelled':
108					// Show cancelled tasks in done column with indicator
109					done.push(task);
110					break;
111			}
112		}
113	
114		// Sort by priority (lower = higher priority)
115		const byPriority = (a: TaskSummary, b: TaskSummary) => a.priority - b.priority;
116		backlog.sort(byPriority);
117		ready.sort(byPriority);
118		inProgress.sort(byPriority);
119		review.sort(byPriority);
120	
121		// Done: most recent first, limit to 20
122		done.sort((a, b) => {
123			const aTime = new Date(a.started_at || a.created_at).getTime();
124			const bTime = new Date(b.started_at || b.created_at).getTime();
125			return bTime - aTime;
126		});
127		const recentDone = done.slice(0, 20);
128	
129		return [
130			{ id: 'backlog', label: 'Backlog', tasks: backlog },
131			{ id: 'ready', label: 'Ready', tasks: ready },
132			{ id: 'in_progress', label: 'In Progress', tasks: inProgress },
133			{ id: 'review', label: 'Review', tasks: review },
134			{ id: 'done', label: 'Done', tasks: recentDone }
135		];
136	}
137	
138	/**
139	 * Format a relative age string from a date.
140	 */
141	export function formatAge(dateStr: string): string {
142		const now = Date.now();
143		const then = new Date(dateStr).getTime();
144		const diffMs = now - then;
145		const diffMins = Math.floor(diffMs / 60000);
146		const diffHours = Math.floor(diffMins / 60);
147		const diffDays = Math.floor(diffHours / 24);
148	
149		if (diffMins < 1) return 'just now';
150		if (diffMins < 60) return `${diffMins}m`;
151		if (diffHours < 24) return `${diffHours}h`;
152		if (diffDays < 30) return `${diffDays}d`;
153		return `${Math.floor(diffDays / 30)}mo`;
154	}
155	
156	/**
157	 * Format elapsed milliseconds to human-readable string.
158	 */
159	export function formatElapsed(ms: number): string {
160		const secs = Math.floor(ms / 1000);
161		const mins = Math.floor(secs / 60);
162		const hours = Math.floor(mins / 60);
163	
164		if (hours > 0) return `${hours}h ${mins % 60}m`;
165		if (mins > 0) return `${mins}m ${secs % 60}s`;
166		return `${secs}s`;
167	}
168	
169	/**
170	 * Parse a VCS ref string into a display label and optional URL.
171	 *
172	 * AC: @ui-task-board ac-3 — VCS info with branch/PR links.
173	 *
174	 * VCS refs can be:
